// ─────────────────────────────────────────────
// SET SCHEMA NODE
// Place this function node just before Validator
// ─────────────────────────────────────────────

msg.schema = {

    // ── Strict mode flags ──────────────────────
    // _strict: false,        // uncomment to allow unknown top-level fields
    // _strictItems: false,   // uncomment to allow unknown fields inside array items


    // ── STRING: basic required ─────────────────
    name: {
        type: 'string',
        required: true,
        minLen: 2,
        maxLen: 80,
        messages: {
            required: 'Full name is required',
            minLen:   'Name must be at least 2 characters',
            maxLen:   'Name must not exceed 80 characters'
        }
    },


    // ── STRING: pattern (email format) ────────
    email: {
        type: 'string',
        required: true,
        maxLen: 255,
        pattern: '^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$',
        messages: {
            required: 'Email is required',
            pattern:  'Enter a valid email address'
        }
    },


    // ── STRING: pattern (phone — raw string, not converted) ──
    phone: {
        type: 'string',
        required: false,
        pattern: '^\\+?[0-9]{7,15}$',
        messages: {
            pattern: 'Enter a valid phone number'
        }
    },


    // ── STRING: allowed values (enum) ─────────
    role: {
        type: 'string',
        required: true,
        allowedValues: ['admin', 'manager', 'operator'],
        messages: {
            required:      'Role is required',
            allowedValues: 'Role must be admin, manager, or operator'
        }
    },


    // ── STRING: optional with max length ──────
    notes: {
        type: 'string',
        required: false,
        maxLen: 500,
        messages: {
            maxLen: 'Notes must not exceed 500 characters'
        }
    },


    // ── NUMBER: integer with min/max ──────────
    age: {
        type: 'number',
        required: true,
        min: 0,
        max: 120,
        precision: 0,        // rounds to whole number
        messages: {
            required: 'Age is required',
            type:     'Age must be a number',
            min:      'Age must be 0 or above',
            max:      'Age must be 120 or below'
        }
    },


    // ── NUMBER: decimal with precision ────────
    price: {
        type: 'number',
        required: true,
        min: 0,
        precision: 2,        // rounds to 2 decimal places e.g. 19.999 → 20.00
        messages: {
            required: 'Price is required',
            type:     'Price must be a number',
            min:      'Price cannot be negative'
        }
    },


    // ── NUMBER: pattern checked BEFORE conversion
    //    (preserves raw format e.g. "007", pin codes) ──
    employeeCode: {
        type: 'number',
        required: false,
        pattern: '^\\d{3}$',   // must be exactly 3 digits e.g. "007" → kept as string before Number()
        messages: {
            pattern: 'Employee code must be exactly 3 digits'
        }
    },


    // ── BOOLEAN: required flag ────────────────
    //    accepts: true/false, "true"/"false", 1/0, "1"/"0", "on"/"off" (HTML checkbox)
    isActive: {
        type: 'boolean',
        required: true,
        messages: {
            required: 'Active status is required',
            type:     'Active status must be true or false'
        }
    },


    // ── BOOLEAN: optional checkbox ────────────
    //    HTML form checkboxes send "on" when checked, nothing when unchecked
    //    If unchecked the field is absent → optional handles it gracefully
    acceptsMarketing: {
        type: 'boolean',
        required: false
    },


    // ── DATE: required ────────────────────────
    //    format: YYYY-MM-DD only
    startDate: {
        type: 'date',
        required: true,
        messages: {
            required: 'Start date is required',
            type:     'Start date must be a valid date (YYYY-MM-DD)'
        }
    },


    // ── DATE: optional ────────────────────────
    endDate: {
        type: 'date',
        required: false,
        messages: {
            type: 'End date must be a valid date (YYYY-MM-DD)'
        }
    },


    // ── ARRAY: simple (no itemSchema) ─────────
    //    validates it is an array with at least 1 item
    //    items are passed through as-is (no per-item type checking)
    tags: {
        type: 'array',
        required: false,
        minItems: 1,
        maxItems: 10,
        messages: {
            type:     'Tags must be an array',
            minItems: 'Provide at least 1 tag',
            maxItems: 'Maximum 10 tags allowed'
        }
    },


    // ── ARRAY: with itemSchema (covers all sub-types) ──
    items: {
        type: 'array',
        required: true,
        minItems: 1,
        maxItems: 100,
        messages: {
            required: 'Order must have at least one item',
            type:     'Items must be an array',
            minItems: 'Order must have at least 1 item',
            maxItems: 'Order cannot exceed 100 items'
        },
        itemSchema: {

            // string — required, pattern
            sku: {
                type: 'string',
                required: true,
                maxLen: 40,
                pattern: '^[A-Z0-9\\-]+$',
                messages: {
                    required: 'SKU is required',
                    pattern:  'SKU must be uppercase letters, numbers, or hyphens'
                }
            },

            // string — allowed values
            category: {
                type: 'string',
                required: true,
                allowedValues: ['electronics', 'clothing', 'food'],
                messages: {
                    required:      'Category is required',
                    allowedValues: 'Category must be electronics, clothing, or food'
                }
            },

            // number — integer
            qty: {
                type: 'number',
                required: true,
                min: 1,
                max: 9999,
                precision: 0,
                messages: {
                    required: 'Quantity is required',
                    type:     'Quantity must be a number',
                    min:      'Quantity must be at least 1',
                    max:      'Quantity cannot exceed 9999'
                }
            },

            // number — decimal
            unitPrice: {
                type: 'number',
                required: true,
                min: 0,
                precision: 2,
                messages: {
                    required: 'Unit price is required',
                    type:     'Unit price must be a number',
                    min:      'Unit price cannot be negative'
                }
            },

            // number — pattern before conversion (e.g. barcode must be exactly 8 digits)
            barcode: {
                type: 'number',
                required: false,
                pattern: '^\\d{8}$',
                messages: {
                    pattern: 'Barcode must be exactly 8 digits'
                }
            },

            // boolean — e.g. gift wrap toggle per item
            isGift: {
                type: 'boolean',
                required: false
            },

            // date — per item dispatch date
            dispatchDate: {
                type: 'date',
                required: false,
                messages: {
                    type: 'Dispatch date must be YYYY-MM-DD'
                }
            },

            // string — optional notes per item
            itemNotes: {
                type: 'string',
                required: false,
                maxLen: 200
            }
        }
    }
};

// Error redirect path for form submissions (browser requests)
// Validator will redirect here with ?errors=... on validation failure
msg.errorRedirectPath = '/orders/new/';

return msg;

