var body = msg.payload || {};

var alert = String(body.alert || "").trim();

var source_recid = body.source_recid ?? null;

if (!alert) {

    var errMsg = { ...msg };

    errMsg.statusCode = 400;

    errMsg.payload = {
        success: false,
        message: "Alert is required."
    };

    return [null, errMsg];
}

msg.topic = `
INSERT INTO alert_dispatch
(
    source,
    source_recid,
    alert_type,
    alert_text,
    sent_on
)
VALUES
(
    ?, ?, ?, ?, CURDATE()
);
`;

msg.payload = [
    "sosalerts",
    source_recid,
    "sos_alert",
    alert
];

return [msg, null];

msg.statusCode = 200;
msg.payload = {
    success: true,
    message: "SOS Alert Saved Successfully"
};
return msg;

// ── Set Schema — POST /sos-alert ──
// sosalert_history.machineid = varchar(100) NULL
// sosalert_history.alert     = varchar(255) NOT NULL

msg.schema = {
    source_recid: {
        type: 'number',
        required: false
    },

    alert: {
        type: 'string',
        required: true,
        minLen: 2,
        maxLen: 255,
        messages: {
            required: 'Alert reason is required.',
            minLen:   'Alert reason must be at least 2 characters',
            maxLen:   'Alert reason must not exceed 255 characters'
        }
    }

};

// SOS.js always sends fetch/XHR, so this redirect path is never
// actually used — set only as a harmless fallback.
msg.errorRedirectPath = 'https://ux.integro.coppercloud.in/app/sos-alerts';

return msg;
